-- PeaklyTest Oct 2026 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'PeaklyTest Oct 2026 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Oct 2026 PeaklyTest · 27 questions · 32 minutes', 32, 100, true, 'PeaklyTest Oct 2026 · Reading & Writing', 1)
