  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('5223979e-ed53-585e-bf82-2e8870b5973c', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical and precise word or phrase?', '["doubts about", "misunderstandings of", "contributions to", "imitations of"]'::jsonb, 1, 'The National Heritage Fellowship was created to honor exceptional folk and traditional artists in the United States. One artist who received the fellowship is taiko drummer Seiichi Tanaka. Tanaka was chosen for his lifetime ______ the arts.'),
  ('06568dab-6887-5db7-b1cd-cdd68d972823', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical and precise word or phrase?', '["Fabricating", "Adapting", "Isolating", "Incorporating"]'::jsonb, 2, '______ the source of a malfunction in a complex electrical system can be a painstaking, time-consuming process: a repair technician may need to test each individual component one by one until the specific part causing the problematic behavior is identified.'),
  ('fdd2ec08-8ebc-5f7b-b158-8f730266f9bc', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical and precise word or phrase?', '["idealistic", "predictable", "timeworn", "innovative"]'::jsonb, 3, 'Though most studies of the effect of altitude on blood chemistry usually concentrate on people who live above sea level, researchers Suleiman A. Al-Sweedan and Moath Alhaj have instead chosen the ______ path in their recent work of studying the blood of people who live below sea level, in locations such as the California towns of Salton Sea Beach and Imperial.'),
  ('8352c7e4-de6e-5e84-bc9e-1c7bf2e4762a', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'As used in the text, what does the word “traces” most nearly mean?', '["Indications", "Debris", "Copies", "Recollections"]'::jsonb, 4, 'The following text is adapted from John Matheus’s 1925 short story “Fog.”

The fog extended its tentacles over city and river, gradually obliterating traces of familiar landscapes. At five-thirty the old Panhandle bridge, supported by massive sandstone pillars, stalwart, as when erected fifty years before to serve a generation now passed behind the portals of life, had become a spectral outline against the sky.'),
  ('373ad494-9189-5adc-b1a5-db982ba0f829', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical and precise word or phrase?', '["affordable", "uncommon", "sufficient", "superficial"]'::jsonb, 5, 'While once ______, basic computer security training that only teaches recognition of obvious scams cannot provide enough protection against today’s sophisticated fake emails, which employ such subtle deception techniques that many organizations now require their staff to complete comprehensive cybersecurity education programs.'),
  ('285888c8-496e-5375-918b-0c73bb6e962f', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice best states the main purpose of the text?', '["To depict the man’s insistence on meeting despite the inconvenience of traveling on horseback", "To compare the upcoming meeting to a far more serious experience from earlier in the man’s life", "To portray the man’s anxiety about the meeting as reflected by his physical state and demeanor", "To contrast the man’s desire to attend the meeting with his awareness of the risk involved in attending it"]'::jsonb, 6, 'The following text is adapted from the 1940 novel The Hamlet by William Faulkner. In rural Mississippi, a man is riding a horse toward the residence of someone he intends to meet with about a business matter.

He was breathing hard but not because he had been galloping. On the contrary, since he had approached near enough to his destination to believe he could have seen smoke if there had been smoke, he had ridden slower and slower. Nevertheless he now sat the horse before the gap in the fence, breathing hard enough through his nose and even sweating a little, looking at the sagging broken-backed cabin set in its inevitable treeless and grassless plot and weathered to the color of an old bee-hive, with that expression of tense and rapid speculation of a man approaching a dud howitzer [artillery] shell.'),
  ('012b1fce-724b-5791-81cf-554f646e6dce', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice best describes the main purpose of the text?', '["To compare career opportunities in modern forestry and explain which positions offer the best job security", "To highlight career opportunities in modern forestry and describe how they integrate scientific knowledge and hands-on work", "To explain technological advances in modern forestry and demonstrate how they’ve transformed traditional practices", "To analyze environmental challenges facing forests and describe how modern professionals address these problems"]'::jsonb, 7, 'Modern forestry offers diverse career opportunities that integrate scientific knowledge with hands-on environmental work. Arborists assess tree health and perform maintenance such as pruning to promote safety and prevent problems. Forestry technicians collect data on growth rates and biodiversity in the wild. Forest ecologists conduct field research and analyze ecosystems to understand how forests respond to changes in weather patterns. With this blend of scientific understanding and practical application, forestry professionals address a variety of complex environmental challenges.'),
  ('c00801c8-4766-5036-a3d6-e29e323d1df2', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It presents a component of the researchers’ methodology that enabled them to convert all prices to the same currency for comparison.", "It describes an aspect of the study design that allowed the researchers to see how buyers in a given country reacted to pricing strategies rarely used in that country.", "It discusses how the researchers controlled for the possibility that pricing strategies could change depending on the goods being sold.", "It explains a step that the researchers took to ensure that their data accurately reflected sellers’ intended prices."]'::jsonb, 8, 'Using data from a global consumer-to-consumer retail website, Alfio Ventura, Eve Sarah Troll, and colleagues evaluated whether pricing approaches vary across countries. Although the website will convert prices to the buyers’ home currency, most sellers target local markets, so <u>the researchers used</u> <u>virtual private networks to collect prices in each country’s predominant currency.</u> They found some striking inter-country differences in pricing strategy, such as the fact that 84.0% of sellers in Puerto Rico price their goods in whole numbers (e.g., \$17) but only 0.3% of sellers in Indonesia do.'),
  ('10faa701-c457-5658-b9fe-773934d75ec2', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'According to the text, how can the color olo be seen?', '["By activating both the long and short cones in the retina", "By activating the long, medium, and short cones in the retina", "By activating only the medium cones in the retina", "By activating only the long cones in the retina"]'::jsonb, 9, 'James Fong and his team claim to have discovered a new color, which they named olo. Olo is a very saturated blue-green color that can’t be seen with the human eye under natural conditions. In the human eye, long, medium, and short cones in the retina help sense bright light and color. Olo can only be seen by activating the medium cones alone. Fong and team activated these cones by using a targeted laser technology to stimulate just the medium cone cells.'),
  ('63ff736d-fe79-5c5d-a2c2-f75176bd4836', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice best states the main idea of the text?', '["According to a team of biologists, black garden ants build larger nests when exposed to a harmful fungus than they otherwise would build.", "A study noted that black garden ants exposed to a harmful fungus tend to dig longer tunnels in their nests instead of reducing the centrality of the nest’s chambers.", "A study found that black garden ants deliberately modify their nest architecture to keep a harmful fungus from spreading.", "A team of scientists noticed that fungal pathogen exposure causes black garden ants to abandon their existing nest structures."]'::jsonb, 10, 'Biologist Nathalie Stroeymeyt and her team found that black garden ants demonstrated a sophisticated form of “architectural immunity.” When confronted with fungal pathogens, these ants modified their excavation patterns in several strategic ways to speed up nest growth, increase spacing between entrances, and reduce the centrality of key chambers (containing the queen, food, or nursery). The team noted that these architectural modifications weren’t random but specifically arranged to minimize fungal spread.'),
  ('f0c1d455-d8ce-5271-a1ee-194e34a9f559', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice most effectively uses data from the graph to complete the statement?', '["the same number of volcanoes that have been active since 1800 as Portugal has.", "no volcanoes that have been active since 1800.", "more volcanoes that have been active since 1960 than Portugal has.", "fewer volcanoes that have been active since 1960 than Portugal has."]'::jsonb, 11, '![figure](/q/oct26/001.webp)

A student is collecting data about countries with volcanoes that have been active in the time since 1800 and in the time since 1960. The student records that Ecuador has ______'),
  ('eeecfbf2-be6d-5334-bb89-dfb281cbebba', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which finding, if true, would be most consistent with Poeplau and his coauthor’s conclusion?', '["Cover crops generally exhibit reduced carbon sequestration rates in fields exposed to high levels of greenhouse gas emissions compared with fields exposed to low levels of those emissions.", "SOC stocks vary more in fields where cover crops have been grown for decades compared with fields where cover crops have only recently been introduced.", "SOC stocks tend to be significantly lower in fields without cover crops compared with fields where cover crops have been grown for several years.", "Teff captures considerably more CO2 in fields where it is the sole cover crop compared with\n\nfields where it is grown alongside other species of cover crops."]'::jsonb, 12, 'Cover crops, such as teff, are planted by many farmers between main growing seasons. While these crops are known for reducing drought stress, Christopher Poeplau and his coauthor argued in a 2015 study that cover crops’ role in supporting soil carbon sequestration deserves more attention. Cover crops remove carbon dioxide (CO2) from the air and convert it to organic compounds; some of these

compounds are stored in the soil as soil organic carbon (SOC), which contributes to the buildup of SOC stocks over time. Based on data from numerous farm fields, Poeplau and his coauthor concluded that cover crops contribute meaningfully to soil carbon sequestration and, if widely adopted, could help offset agricultural emissions of atmospheric CO2 and other greenhouse gases.'),
  ('8aaa92fc-2f42-56c7-85e3-7a166735560f', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice most effectively uses data from the graph to complete the assertion?', '["those that filed Form 4720 in 2003 because they failed to meet the minimum charitable distribution requirement collectively paid a larger percentage of the total penalty assessed that year than those that filed Form 4720 in 2005 for the same reason.", "those that filed Form 4720 because they engaged in self-dealing paid an increasing percentage of the total penalty each year from 2003 to 2005.", "those that filed Form 4720 because they had excess holdings in a business enterprise paid, on average, a larger penalty than those that filed Form 4720 because they engaged in self-dealing.", "those that filed Form 4720 in 2005 because they engaged in self-dealing collectively paid a larger percentage of the total penalty assessed that year than those that filed Form 990 but"]'::jsonb, 13, '![figure](/q/oct26/002.webp)

While US public charities, like Kaiser Foundation Hospitals, must file Form 990 yearly with the IRS, private foundations, such as Lilly Endowment Inc., must file a different form, 990-PF. In addition, foundations that engage in certain prohibited activities must also file Form 4720 and pay a penalty tax on the money involved. Private foundations are prohibited from holding excess interests in a business enterprise, “self-dealing” (conducting activities that benefit foundation insiders), making taxable expenditures such as grants to noncharitable entities, and failing to cross a required threshold in making charitable distributions from income. Out of the organizations that filed Form 990-PF in the years 2003–2005, ______'),
  ('7b297ec3-ce8c-5a39-984c-a545fb4d61bd', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice most effectively uses a quotation from the first act of The Vortex to illustrate the underlined claim?', '["Pawnie exclaims his distaste for a particular lampshade, to which Helen responds, “I gave it to [Florence] last Christmas.”", "Helen comments that the home’s decorations are not offensive to her tastes, to which Pawnie sarcastically replies, “Dear Helen, you’re such a loyal friend.”", "Pawnie suggests that Clara would prefer him to leave the room, to which Clara responds, “No, Pawnie, I should never expect the least consideration from you.”", "Helen says she wonders about Florence’s future, to which Pawnie replies, “My dear, I’m far too occupied in wondering what’s going to happen to me to worry about other people.”"]'::jsonb, 14, 'The Vortex is a 1924 satirical play by Noël Coward. During the first act of the play Pawnie, Clara, and Helen are at the home of Florence, whose arrival they are awaiting. <u>In this act, Coward conveys the idea that</u> <u>other characters consider Pawnie to be a thoughtless person.</u>'),
  ('7da6433a-f68c-5316-91df-a5634c0f31be', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice most logically completes the text?', '["implying his belief that both figurative and abstract art can portray the complexity of tribal identity.", "suggesting that even when practiced by Indigenous artists, abstract forms of art are ill-suited to portraying tribally specific content.", "transmitting his culture through particularities of content rather than through a tribally specific painting technique.", "casting doubt on the feasibility of developing a new style of painting grounded in traditionally figurative art forms."]'::jsonb, 15, 'Muscogee painter Starr Hardridge often eschews the European tradition of figurative painting, with its proportionality of human form and depth between foreground and background; instead, he assembles compositions out of abstract motifs common in the traditional beadwork and graphic art of his own tribe, thus ensuring cultural continuity. Cree painter Kent Monkman, on the other hand, works in the European figurative mode; however, he draws his subject matter from cultural traditions that predate the European colonization of the lands of his own tribe, thereby ______'),
  ('57b6a646-f1b8-55ec-a7a5-b5489c7bbef1', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["areas", "areas, who", "areas; they", "areas,"]'::jsonb, 16, 'Home to the city of El Paso, the far western corner of Texas follows Mountain time rather than Central time. As a result, people in El Paso and the surrounding ______ must set their clocks one hour behind those in the rest of the state.'),
  ('87fd6a69-3a01-5662-87bf-c62030fc4461', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["rose", "will rise", "had risen", "rises"]'::jsonb, 17, 'Mount Meru ranks among the world’s tallest mountains. Specifically, the peak’s highest point ______ 14,977 feet above sea level.'),
  ('d9177ba1-168e-54a4-b9f1-02cc09b9a119', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["this activity effectively uncovers potential problems early,", "teams effectively uncover potential problems early with this activity,", "potential problems are effectively uncovered by this activity early,", "effective uncovering of potential problems by the team in this activity is done early,"]'::jsonb, 18, 'A premortem is an exercise in which teams imagine their project has already failed, then brainstorm possible reasons for that failure. Despite its apparent pessimism, ______ prompting teams to proactively develop mitigation strategies during the planning stage. As a result, the project is more likely to succeed.'),
  ('f7bd213e-84d0-5940-9401-c4bf1302ef63', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["box,", "box", "box—", "box:"]'::jsonb, 19, 'To more easily balance the weight of her body on her toes while performing the demanding pointe work that became increasingly common in early 20th-century ballet, internationally known ballerina Anna Pavlova redesigned her pointe shoes. The modifications she made—adding a stiffened leather sole and hardened toe ______ began the modernization of ballet’s iconic footwear.'),
  ('4ae1b7c4-a1e4-5fab-99ce-179de7bafa6f', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["threefold: to", "threefold; to", "threefold to", "threefold. To"]'::jsonb, 20, 'Archaeological evidence indicates that board games have existed in human societies for at least five millennia, with examples discovered in the tombs of ancient Egypt and the ruins of Mesopotamia. The purpose of these ancient games was ______ provide entertainment during leisure time, to reflect cultural beliefs, and to develop strategic thinking skills among players.'),
  ('9f45d9b9-60e0-50f7-be0f-a842eb48b47e', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are focused", "focusing", "have focused", "focus"]'::jsonb, 21, 'Theoretical physicists have begun to develop novel methods for detecting dark matter. Certain approaches ______ on quantum collective phenomena, like phonons in crystals or excitations in superfluid helium, are likely to face significant challenges, acknowledges physicist Kathryn Zurek, unless researchers can reduce background processes that might mimic the signals they’re attempting to detect.'),
  ('89f58e60-bbdd-5173-b4f2-701cc49c0c7f', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical transition?', '["In other words,", "In conclusion,", "Similarly,", "As a result,"]'::jsonb, 22, 'Humans inherit specific physical traits (like having blue or hazel eyes) from their parents. ______ cats inherit specific physical traits (like having brown or white fur) from their parents.'),
  ('3ed142e6-128e-50c9-bb74-63cb0f8ef15b', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "Specifically,", "In conclusion,", "Alternatively,"]'::jsonb, 23, 'Scientists studying forest restoration have discovered that trees depend on complex partnerships with microscopic organisms for survival. The researchers found that special fungi called endophytes live inside tree leaves and serve as a defense mechanism. ______ these endophytes help by fighting off diseases and boosting the tree’s immune system.'),
  ('1255939c-91de-5bd5-8140-caf3a5ef441e', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'Which choice completes the text with the most logical transition?', '["However,", "For this reason,", "For example,", "Nevertheless,"]'::jsonb, 24, 'A team led by Portuguese researcher Isabel C.F.R. Ferreira found that many species of mushrooms contain chemicals called phenolic compounds, such as 5-O-caffeoylquinic acid and kaempferol. ______ Ferreira detected 5-O-caffeoylquinic acid in Pleurotus ostreatus mushrooms and kaempferol in Sparassis crispa mushrooms.'),
  ('55ed6fe7-88b2-5a86-bc0b-69b479e4d5e2', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'The student wants to introduce pistol shrimp to an audience unfamiliar with these crustaceans. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Some crustaceans use a specialized claw to create high-speed water jets and a bubble that stuns the small fish they prey on.", "Pistol shrimp are small marine creatures that use a specialized oversized claw to generate shock waves powerful enough to stun small fish.", "Pistol shrimp are preyed on by small marine crustaceans that create high-speed water jets to stun their prey.", "Pushing water through a narrow groove at extreme speeds, the snapping shut of the shrimp’s claw sets the shock-wave hunting process in motion."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Pistol shrimp are small marine crustaceans that hunt using a specialized oversized claw. When the claw snaps shut rapidly, it pushes water through a narrow groove at extreme speeds. This high-speed water jet creates a bubble that pops forcefully near the shrimp’s prey. The popping bubble generates shock waves powerful enough to stun small fish.'),
  ('0e706c69-109e-5d1c-a313-ee4a0cb01bf0', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'The student wants to provide an example of one of Catlett’s sculptures. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The sculpture Rejecting Injustice was created by celebrated artist Elizabeth Catlett in 2003.", "Artist Elizabeth Catlett is best known for creating sculptures and prints that explore the Black experience.", "The print Survivor was created by celebrated artist Elizabeth Catlett in 1983.", "Elizabeth Catlett, a celebrated artist, was born in 1915."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Elizabeth Catlett (1915–2012) was a celebrated African American artist.
She is best known for creating sculptures and prints that explore the Black experience. Rejecting Injustice is a 2003 sculpture by Catlett.
Survivor is a 1983 print by Catlett.'),
  ('4631442d-4968-54e0-afa0-195ff34c27a1', 'c13a9e11-6e09-5ee4-bc1e-39e77dc56cbc', 'The student wants to emphasize the 2020 population of Tlaxcoapan. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["As a municipality in Hidalgo, Tlaxcoapan is responsible for providing public services to its population.", "In 2020, the municipality of Tlaxcoapan had a population of 28,626.", "As of 2020, Tlaxcoapan was one of 84 municipalities in Hidalgo, Mexico.", "Home to 26,758 people, the governmental region was responsible for providing street lighting to its population in 2010."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Tlaxcoapan is a municipality in the state of Hidalgo, Mexico.
Municipalities are governmental regions responsible for providing many public services to their residents.
One service they provide is street lighting.
Tlaxcoapan’s population was 28,626 in 2020.
Its population was 26,758 in 2010.
Hidalgo is divided into 84 municipalities.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('5223979e-ed53-585e-bf82-2e8870b5973c', 2, null, 'A fellowship honoring an artist recognizes "contributions to" the arts.'),
  ('06568dab-6887-5db7-b1cd-cdd68d972823', 2, null, 'Testing parts one by one to find the faulty one is "isolating" the source.'),
  ('fdd2ec08-8ebc-5f7b-b158-8f730266f9bc', 3, null, 'Studying people below sea level departs from the usual approach: an "innovative" path.'),
  ('8352c7e4-de6e-5e84-bc9e-1c7bf2e4762a', 0, null, 'The fog erased signs of the familiar landscape: "indications."'),
  ('373ad494-9189-5adc-b1a5-db982ba0f829', 2, null, 'Basic training was once enough but no longer is: "sufficient."'),
  ('285888c8-496e-5375-918b-0c73bb6e962f', 2, null, 'Heavy breathing, sweating and "tense and rapid speculation" show his anxiety about the meeting.'),
  ('012b1fce-724b-5791-81cf-554f646e6dce', 1, null, 'It surveys forestry careers and how each combines science with hands-on work.'),
  ('c00801c8-4766-5036-a3d6-e29e323d1df2', 3, null, 'Collecting prices in local currency captures the prices sellers actually set.'),
  ('10faa701-c457-5658-b9fe-773934d75ec2', 2, null, 'Olo "can only be seen by activating the medium cones alone."'),
  ('63ff736d-fe79-5c5d-a2c2-f75176bd4836', 2, null, 'The ants deliberately changed their nest layout to limit fungal spread.'),
  ('f0c1d455-d8ce-5271-a1ee-194e34a9f559', 2, null, 'Since 1960, Ecuador has 11 active volcanoes and Portugal has 1.'),
  ('eeecfbf2-be6d-5334-bb89-dfb281cbebba', 2, null, 'Higher SOC where cover crops have grown for years supports their role in storing carbon.'),
  ('8aaa92fc-2f42-56c7-85e3-7a166735560f', 0, null, 'Undistributed income was about 79% of penalties in 2003 but about 55% in 2005.'),
  ('7b297ec3-ce8c-5a39-984c-a545fb4d61bd', 2, null, 'Clara says she "should never expect the least consideration" from Pawnie: she sees him as thoughtless.'),
  ('7da6433a-f68c-5316-91df-a5634c0f31be', 2, null, 'Monkman uses a European technique but Indigenous subject matter, so his culture comes through content.'),
  ('57b6a646-f1b8-55ec-a7a5-b5489c7bbef1', 0, null, '"people in El Paso and the surrounding areas" is the subject; no punctuation before the verb.'),
  ('87fd6a69-3a01-5662-87bf-c62030fc4461', 3, null, 'A current, permanent fact: "rises."'),
  ('d9177ba1-168e-54a4-b9f1-02cc09b9a119', 0, null, '"Despite its apparent pessimism" describes the activity, so "this activity" must be the subject.'),
  ('f7bd213e-84d0-5940-9401-c4bf1302ef63', 2, null, 'The aside opened with a dash after "made," so it closes with a dash.'),
  ('4ae1b7c4-a1e4-5fab-99ce-179de7bafa6f', 0, null, 'A colon introduces the list of three purposes.'),
  ('9f45d9b9-60e0-50f7-be0f-a842eb48b47e', 1, null, '"focusing on..." is a participial phrase modifying "approaches"; the main verb is "are likely."'),
  ('89f58e60-bbdd-5173-b4f2-701cc49c0c7f', 2, null, 'Cats inherit traits just like humans: "Similarly."'),
  ('3ed142e6-128e-50c9-bb74-63cb0f8ef15b', 1, null, 'The sentence details how endophytes defend the tree: "Specifically."'),
  ('1255939c-91de-5bd5-8140-caf3a5ef441e', 2, null, 'The mushroom species are examples of the general finding: "For example."'),
  ('55ed6fe7-88b2-5a86-bc0b-69b479e4d5e2', 1, null, 'It names pistol shrimp, says what they are, and explains their notable hunting method.'),
  ('0e706c69-109e-5d1c-a313-ee4a0cb01bf0', 0, null, 'Rejecting Injustice is a sculpture by Catlett.'),
  ('4631442d-4968-54e0-afa0-195ff34c27a1', 1, null, 'It states the 2020 population: 28,626.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Oct 2026 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('8cdf1444-799e-58a7-b5dd-ce54add2801a', 'PeaklyTest Oct 2026 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Oct 2026 PeaklyTest · 27 questions · 32 minutes', 32, 101, true, 'PeaklyTest Oct 2026 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('7aba587c-1d9a-525d-94ab-8a4ab2b04848', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical and precise word or phrase?', '["interplay", "resolution", "neglect", "misinterpretation"]'::jsonb, 1, 'Weather patterns, market trends, input costs, labor availability, equipment maintenance, and biological cycles are all variables that farmers must consider separately and in terms of how they may affect each other, and it is this ______ of factors in particular that makes successful farm management so challenging.'),
  ('0582e097-7224-52b9-8d3c-ffa8ceb6951d', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical and precise word or phrase?', '["liability", "overhead", "staffing", "throughput"]'::jsonb, 2, 'To maximize ______, package distribution centers employ advanced scheduling systems and strategic staging areas that allow for goods received from warehouses to be immediately transferred to trucks for delivery to their final destinations. Some centers are so efficient that even the largest delivery trucks can be filled in a matter of minutes.'),
  ('27b9c50d-36fa-5a26-b92f-d0e288817962', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical and precise word or phrase?', '["anomalies", "optimizations", "parameters", "predictions"]'::jsonb, 3, 'Researchers have developed algorithms that take into account how various ______ influence production schedules, allowing rapid solution generation for manufacturing planning problems. The algorithms help identify efficient production schedules by processing those quantifiable inputs (e.g., demand patterns and capacity constraints) without exhaustively testing all possible scenarios.'),
  ('17f52ca8-c024-5e91-be6d-00c66e7ea807', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical and precise word or phrase?', '["exonerations", "admonitions", "obfuscations", "venerations"]'::jsonb, 4, 'The Invisible Girl’s ability to turn invisible is illustrative of the lamentably lackluster powers bestowed on many female superheroes, but even those with more formidable powers have been subject to unflattering portrayals that often serve as ______: as the Phoenix, Jean Grey loses control of a cosmic force and destroys an entire planet, showing the corrupting influence of power.'),
  ('7ac87c0f-8f98-58dd-a602-1ff4add9cf55', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It acknowledges an exception to the pattern described in the first sentence of the text.", "It describes a natural phenomenon that is explained later in the text.", "It discusses a natural occurrence that leads to the consequences explained later in the text.", "It presents a research finding that challenges the view mentioned in the first sentence of the text."]'::jsonb, 5, 'Research on minor solar eruptions in magnetically quiet regions reveals an interesting pattern. <u>Material</u> <u>expelled during these events follows a narrow arc trajectory back to the Sun’s surface.</u> High-resolution images show these eruptions produce thin streams of hot gas moving at speeds between 55 and 200 kilometers per second. Although these are impressive velocities, they are not sufficient to overcome the confining forces of the Sun’s gravity and magnetic field, so the material is pulled back down.'),
  ('34c7ebdd-bd2e-56af-b52d-7dba1cb5e485', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It provides a specific illustration of the point the novel’s author makes about the spread of digital dystopia.", "It describes an example of a technological solution that the novel presents as environmentally conscious but that in actuality would prevent meaningful systemic change.", "It explains how the protagonist’s perspective on the company evolves from sincere to cynical over the course of the novel’s plot.", "It conveys how the novel’s central message is advanced through a series of increasingly satirical anecdotes."]'::jsonb, 6, 'In Dave Eggers’s novel The Every, protagonist Delaney Wells infiltrates a monopolistic technology company with the intention to destroy it. Instead, she becomes ensnared in its corporate ideology. <u>She</u> <u>even helps the company launch an app that awards points for sustainable purchases while publicly</u> <u>shaming users with high carbon footprints.</u> Through this satirical portrayal, Eggers drives home his central message: digital dystopia spreads not through coercion but through willing participation in technologies that promise social change but that encourage self-centered and moralizing behavior rather than collective action to bring about systemic improvements.'),
  ('038929fd-e9fc-5e29-91bc-e0c7e1bc6017', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice best describes a notable difference in how the references to palm trees function in Text 1 and Text 2?', '["While the narrator of Text 1 and the author of Text 2 both discuss palm trees to suggest the value of experiencing the natural world, only the narrator of Text 1 alludes to the labor that goes into cultivating real palm trees.", "While palm trees form part of a series conveying the variety of the natural world in both texts, only the author of Text 2 recognizes how closely interconnected palm trees are with other plants in their environment.", "While the narrator of Text 1 and the author of Text 2 both refer to metaphorical palm trees, only the narrator of Text 1 suggests that the palm trees are representative of home.", "While palm trees serve to evoke natural beauty in both texts, only the author of Text 2 expresses a close sense of identification with palm trees."]'::jsonb, 7, 'Text 1 is from George Eliot’s 1860 novel The Mill on the Floss. Text 2 is from Rabindranath Tagore’s 1921 nonfiction book Glimpses of Bengal.

**Text 1**

The wood I walk in on this mild May day, with the young yellow-brown foliage of the oaks between me and the blue sky, the white star-flowers and the blue-eyed speedwell and the ground ivy at my feet, what grove of tropic palms, what strange ferns or splendid broad-petalled blossoms, could ever thrill such deep and delicate fibres within me as this home scene?

**Text 2**

My feelings seem to be those of our ancient earth in the daily ecstasy of its sun-kissed life; my own consciousness seems to stream through each blade of grass, each sucking root, to rise with the sap through the trees, to break out with joyous thrills in the waving fields of corn, in the rustling palm leaves.'),
  ('56acb438-7f6e-5730-8c7c-77d3a19d913c', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Information in the text best supports which statement about the consonant s?', '["The pronunciation of this consonant in Nahuatl may have been affected by its pronunciation in Mexican Spanish.", "The pronunciation of this consonant requires greater tension in the tongue in Nahuatl than in Castilian.", "This consonant appears in a higher percentage of Nahuatl vocabulary than of Castilian vocabulary.", "The pronunciation of this consonant is the principal difference between the Mexican and Castilian dialects of Spanish."]'::jsonb, 8, 'In the Mexican dialect of Spanish, the consonant s is pronounced with greater tension in the tongue than it is in Castilian, the dominant dialect in Spain, resulting in a sharper sound. Margarita Hidalgo, a linguist at San Diego State University, argues that Mexican Spanish acquired this pronunciation from Nahuatl, the language of the Nahua people in Central Mexico: as the Spanish colonizers of Mexico incorporated Nahuatl words into their speech, and as more and more Nahuas spoke Spanish as a second language, the Nahuatl pronunciation of the s consonant replaced the Castilian pronunciation.'),
  ('37921344-f76f-5ff2-a190-0622c7afa49f', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which quotation from a literary critic would be the most effective evidence in support of the underlined claim?', '["“Not all the stories anthologized in The Big Book of Cyberpunk were first published as stand-alone short stories in magazines or journals: for example, qntm’s 2021 story ‘Lena’ was originally self-published on the author’s site qntm.org.”", "“The stories in The Big Book of Cyberpunk share a number of common themes indicative of cyberpunk as a whole: body modification; resistance to authority; the ways in which technological advancements alter human behavior.”", "“Shurin’s characterization of cyberpunk is remarkably generous: it is a categorization that might well serve for the entire field of science fiction in general, rather than cyberpunk in particular.”", "“A key component of cyberpunk that differentiates it from other subgenres of science fiction is an affection for the totems of 1980s pop culture, such as the mirrored sunglasses that were then popular.”"]'::jsonb, 9, 'Editor Jared Shurin’s enormous 2023 anthology The Big Book of Cyberpunk comprises 108 stories. Shurin’s volume is chronologically expansive, featuring such stories as James Tiptree Jr.’s “The Girl Who Was Plugged In” (1973) and Lavanya Lakshminarayan’s “Études” (2020). In his introduction, Shurin defines cyberpunk as a subgenre of speculative fiction concerning “the influence of technology on the scale, the pace, or the pattern of human affairs”; however, some critics assert that <u>cyberpunk is a literary</u> <u>movement that is in large part aesthetic rather than idea driven.</u>'),
  ('6830efd4-7711-5388-b140-600cbfe3a5ae', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice most effectively uses the data from the table to complete the text?', '["vocal responses to later recordings were on average 3.2 seconds longer than responses to earlier recordings, a change that was statistically significant.", "later recordings had a more significant effect on change in peak frequency than on change in song duration, as shown by p-values of 0.4 and 0.002, respectively.", "vocal responses were likely affected by extraneous factors in addition to the position of recordings, as shown by the wider range of t-values relative to the narrower range of p-values.", "the position of recordings had a significant effect on change in song rate and change in song duration, as shown by p-values of 0.03 and 0.002, respectively."]'::jsonb, 10, '**T-values and P-values for the Relationship between Recording Position and Change in Song** **Characteristics**

| Song characteristic | T-value | P-value |
| **Change in peak frequency (Hz)** | −1.0 | 0.4 |
| **Change in song rate (songs/min)** | −2.2 | 0.03 |
| **Change in song duration (s)** | −3.2 | 0.002 |

Erin Grabarczyk and Sharon Gill analyzed changes in house wrens’ song characteristics following playback of serialized recordings mimicking environmental noise. Because recordings earlier in a series may have carryover effects that influence vocal responses to later recordings, the effects of a recording’s position within a series on changes in song characteristics were also evaluated. Larger absolute t-values indicate stronger evidence that song characteristics change systematically with recording position (negative t-values show that characteristics decreased), while p-values below 0.05 suggest that the effects of recording position on song characteristics are statistically significant. The researchers concluded that the possibility of carryover effects cannot be excluded, given that ______'),
  ('6d9d4cc7-3370-523a-a3e9-c02560831bd3', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which quotation from a literary scholar would most directly support the underlined claim?', '["“Seriality in Mackey’s long song operates recursively, meaning that, in combination with the work’s marshaling of an eclectic array of cultural allusions, it endlessly reiterates and recontextualizes the same archetypal images and narrative incidents, uncovering in these elements new and unexpected meanings with each repetition.”", "“The intellectual scope of Mackey’s work is capacious, drawing on such wide-ranging cultural influences as the traditional stories of the Dogon people of West Africa, philosophical schools of the ancient Mediterranean, the history of the African diaspora, quantum mechanics, modernist poetry, and experimental jazz music.”", "“Though nominally an epic whose band of wandering travelers evoke the ancient Greek epic hero Odysseus, unlike traditional Western epics, which often conclude with the hero’s return home, Mackey’s long song possesses an open-endedness that renders the final homecoming elusive.”", "“Though at the outset of his project Mackey conceived of Song of the Andoumboulou and Mu as two discrete series, in the preface of 2006’s Splay Anthem, Mackey indicates that their seriality eventually enabled his realization that they were in fact two facets of a single work.”"]'::jsonb, 11, 'The 2021 poetry collection Double Trio continues Nathaniel Mackey’s “long song,” a sprawling work that consists of a pair of serialized poems called Song of the Andoumboulou and Mu, whose joint publication spans multiple installments over several decades. In this long song, Mackey actualizes what he calls “discrepant engagement,” a compositional strategy that involves continuously revising and remixing diverse cultural references to illuminate the complex interconnectedness of global cultures. <u>Mackey’s</u> <u>long song’s open-endedness is essential to the way it manifests discrepant engagement—that is, the</u> <u>work’s associative logic and resistance to linear narrative prevent readers from imposing a definitive and</u> <u>coherent interpretation on its presentation of world cultures.</u>'),
  ('ad64f3c3-c276-5a95-862c-80e84323963c', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice most effectively uses data from the table to complete the example?', '["Saser Kangri I / K22 has an elevation of 7,672 meters and is considered the highest mountain from the Saser Karakoram range.", "Nanda Devi has a much higher prominence than does Langpo.", "Nanda Devi has a high prominence but is from a different mountain range than Rimo I, which has a lower prominence.", "Nanda Devi has an elevation of 7,816 meters but a considerably lower prominence of 3,139 meters."]'::jsonb, 12, '**Highest Major Summits in India**

| Summit | Elevation (meters) | Mountain range | Prominence (meters) |
| **Rimo I** | 7,385 | Rimo Karakoram | 1,438 |
| **Nanda Devi** | 7,816 | Himalayas | 3,139 |
| **Panchchuli II** | 6,904 | Garhwal Himalaya | 1,614 |
| **Saser Kangri I / K22** | 7,672 | Saser Karakoram | 2,304 |
| **Langpo** | 6,965 | Sikkim Himalaya | 560 |

Mountain summits are often described in terms of their elevation, or height above sea level. But a summit’s elevation may not be as good an indication of how high the mountain appears to observers as is the summit’s prominence, or its height above its surroundings, and these values can differ significantly. For example, the Indian mountain of ______'),
  ('cbd8e4b5-a1d2-5b8c-ad71-2c8a9443f60a', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice most logically completes the text?', '["the study by Ferster reliably represents handedness in captive primates but not in wild primates.", "neither the study by Ferster nor the study by McGrew and colleagues provides sufficient evidence to make a meaningful comparison about handedness in primates.", "the study by Ferster reliably represents handedness in captive primates, but the study by McGrew and colleagues likely does not reliably represent handedness in wild primates.", "McGrew and colleagues likely underestimated the prevalence of right-handedness among the wild chimpanzees in the study."]'::jsonb, 13, 'Whereas Charles B. Ferster’s 1957 study of a captive chimpanzee reported more right-handedness than left-handedness, William C. McGrew and colleagues’ 1999 study of wild chimpanzees did not. According to a meta-analysis of studies of nonhuman primates, captive populations are more likely to be described as right-handed than wild populations are. Statistical analysis indicates a handedness study would need a minimum of 176 individuals to show a representative result; however, the study by Ferster included a total population of 1, and the study by McGrew and colleagues included a total population of 13. This suggests that ______'),
  ('a991cb56-62aa-5e76-84ee-58ff085cad4c', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice most logically completes the text?', '["the brain regions associated with sensory-motor functions are often involved in general comprehension, even in contexts that don’t involve descriptions of physical movement.", "the specific combination of brain regions involved in comprehending speech is likely contingent on the total context in which the speech is embedded.", "the areas of the brain that activate when processing speech will typically include areas primarily responsible for nonlinguistic functions, although the exact combination of areas may be impossible to determine.", "the brain regions most strongly associated with affective processing activate whenever a listener believes an utterance has emotional connotations, even if the speaker did not intend those connotations."]'::jsonb, 14, 'While the brain regions most strongly associated with language tasks have some modularity in that different language tasks activate these areas to varying degrees, comprehension also invokes other areas of the brain more strongly associated with nonlinguistic functions. For example, understanding a description of a person performing physical actions might call on parts of the listener’s brain associated with sensory-motor functions, whereas a highly emotive account will likely activate areas associated with affective processing. Thus, beyond the areas most strongly associated with linguistic functions, ______'),
  ('a6ca75d7-04d5-591e-88ae-54d560cfd9ef', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice most logically completes the text?', '["as a tree species in temperate forests becomes more abundant, individuals of that species are more likely to be found near conspecifics, enabling abundant species to exploit localized resources to a greater extent than rare species can.", "while an increase in abundance in one tree species often leads to a reduction in abundance of nearby species, temperate tree species tend to play different roles in the same ecosystem, reducing the expected effect of abundance on aggregation.", "although rare tree species in temperate forests encounter relatively high local competition from conspecifics, they can thrive by exploiting resources that are underexploited by other local species.", "even though rare tree species in temperate forests tend to cluster with conspecifics more than rare tree species in tropical forests do, they are sufficiently rare locally that they benefit from RSA more than rare tropical species do."]'::jsonb, 15, 'Rare species advantage (RSA) describes the situation in which there are few conspecifics (other members of the same species) in an organism’s immediate surroundings, enabling the organism to avoid competition with conspecifics for the same resources; RSA is widely believed to play a crucial role in maintaining ecological stability. Among tree species in the Xishuangbanna rainforest plot (latitude 21.61° N) and other tropical forest sites, there is little correlation between conspecific aggregation and the abundance of a given species in the wider local area, so RSA is expected, but in the Harvard Forest (latitude 42.54° N) and other temperate forest sites, the aggregation-abundance correlation for tree species is strongly negative. Mathematical modeling suggests, however, that niche distinction may mitigate the apparent risk to temperate ecological stability engendered by this pattern: ______'),
  ('10c8efb7-55aa-5c5f-9c55-e7def1bbb77a', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["age and built", "age, built", "age: built", "age built"]'::jsonb, 16, 'Extensive radiocarbon dating of reed samples from Caral confirmed Ruth Shady Solís’s hypothesis about the Peruvian site’s ______ nearly 5,000 years ago, the ancient city preceded the Olmec civilization to the north by a full millennium, a revelation that fundamentally altered our understanding of urban development in the Western Hemisphere.'),
  ('99286ad7-2683-58c8-b4ce-9bd666b1fea8', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is", "has been", "was", "were"]'::jsonb, 17, 'Chemists investigating the properties of coal tar in the mid-nineteenth century discovered compounds that led to the creation of vibrant artificial colorants. Commercial applications of this new synthetic dye technology—beginning with the purple dye called mauve, discovered by William Perkin in 1856—______ responsible for launching what one science historian calls a “manufacturing revolution based on chemistry.”'),
  ('48ca3cdd-4c69-5695-aa1b-8f43ce6c98eb', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["dictates", "dictating", "dictated", "was dictating"]'::jsonb, 18, 'The statement “all cats have whiskers” is scientific because it could be proved false by a single observation to the contrary, according to Karl Popper. Popper’s theory ______ that scientific hypotheses must be refutable, termed the criterion of falsifiability, rejects the confirmationist position that uses verifiability as the standard for scientific hypotheses.'),
  ('17451dc5-8518-5063-9ce3-d23817fd2557', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["seeking", "had sought", "sought", "were seeking"]'::jsonb, 19, 'During a recent investigation, archaeologists ______ an explanation for the consistent and seemingly deliberate placement of petroglyphs (rock carvings) near water analyzed several sites on Caribbean islands. They discovered that many of the pools near petroglyphs had consistent water levels year-round, creating perfect reflecting surfaces for the carved symbols on the rocks.'),
  ('747cb15b-06fc-5662-a374-3ba25aaaebe6', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Robin,” a technique that", "Robin.” A technique that", "Robin”—a technique that,", "Robin”; a technique that,"]'::jsonb, 20, 'For his mash-up “Smells Like Rockin’ Robin,” DJ Mark Vidler layered Kurt Cobain’s minor-key vocals from “Smells Like Teen Spirit” over the Jackson 5’s major-key blues progression from “Rockin’ ______ by inserting the grunge singer’s vocal lines as pitch-shifted “blue notes” within the pop-soul group’s harmonic framework, creates an intensified “bluesy” feeling and subverts the expectations of listeners familiar with either musical source.'),
  ('23a3a2cf-c16f-535f-b333-b454aa5b7288', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["star). Occurring", "star), occurring", "star) and occurring", "star) occurring"]'::jsonb, 21, 'Named for the year in which it was detected by American astronomers, SN 2008D was a supernova (the explosion of a massive ______ in the constellation Lynx, 88 million light-years from Earth, the transient yet powerful blast propelled particles and debris into space at extremely high speeds.'),
  ('3fab4c26-bfa1-5b32-89b8-c6ef8cb04c89', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical transition?', '["Thus,", "Furthermore,", "Instead,", "Similarly,"]'::jsonb, 22, 'The Hornbostel-Sachs system classifies musical instruments by how they produce sound. For example, an instrument that is popular in Myanmar called the saung-gauk produces sound primarily through the vibration of its strings. ______ under the Hornbostel-Sachs system, the saung-gauk is a chordophone.'),
  ('fb4ef6b8-91e6-5629-ad5b-e4e3bd214948', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical transition?', '["however,", "for example,", "meanwhile,", "additionally,"]'::jsonb, 23, 'Generally, sleek vehicles are more aerodynamic than bulkier ones. The streamlined nose of the Northrop F-5 jet, ______ helps it glide through wind with relative ease, while a boxy semitruck encounters more wind resistance, making it less aerodynamic.'),
  ('c8782dca-d79a-5291-99dc-b790cf325243', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical transition?', '["In fact,", "Similarly,", "Regardless,", "First of all,"]'::jsonb, 24, 'Japanese conceptual artist On Kawara focused his artistic career on recording the passage of time in simple ways. For example, MAY 22, 1979 is one of over three thousand paintings by Kawara on which he recorded the date in bold white strokes on a monochrome background. ______ I Got Up at 8.18 A.M., Jun 22 1977 is one of a series of postcards—this one of New York City’s Greenwich Village—that Kawara titled after the postcard’s message, which informed a friend of when Kawara got up that day.'),
  ('1492f34b-7beb-526f-a2ac-e1622e9a86d3', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'Which choice completes the text with the most logical transition?', '["In addition,", "Indeed,", "Therefore,", "Nevertheless,"]'::jsonb, 25, 'On August 22, 1928, US Olympians received a ticker-tape parade in New York City in recognition of their participation in the 1928 Olympic Games. Of the 206 ticker-tape parades held between 1886 and 2022, a number were for achievements in sports. ______ the 1928 Olympians’ parade was just one of 7 honoring Olympic athletes.'),
  ('cbb9c9c8-ee89-5b04-b73a-a57a5672db9d', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'The student wants to contrast the subject matter of the two prints. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The scenes depicted in both works were first carved onto a printing block, then stamped onto paper; however, one work is a linocut, while the other is a relief print.", "The print by Cortéz is a color linocut; by contrast, Andrews’s is a relief print.", "Andrews made Hyde Park in 1931, while Cortéz made ¡Será toda nuestra! (“It will all be ours!”) later, in 1977.", "Cortéz’s print expresses an explicitly political point of view, while Andrews’s depicts a tranquil, everyday scene."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Hyde Park is a 1931 color linocut print by Canadian artist Sybil Andrews.
It depicts a tranquil, everyday scene (a spring day in a city park).
¡Será toda nuestra! (“It will all be ours!”) is a 1977 color linocut print by Mexican American artist Carlos Cortéz.
It features a scene with an explicitly political point of view (a group of laborers preparing to go on strike).
Relief printing is a technique in which an image is carved onto a printing block, covered in ink or paint, and stamped onto paper.
Lino cutting is a type of relief printing that uses linoleum tile as the printing block.'),
  ('63ef781c-ff84-51e2-87c5-ee997ea905e4', '8cdf1444-799e-58a7-b5dd-ce54add2801a', 'The student wants to explain why ERW is a superior method for capturing CO2. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["ERW improves soil health and helps farmers increase their income from selling carbon credits.", "ERW removes CO2 from the air in a way that is both low-cost and low-tech.", "ERW is a method of spreading crushed basalt on farmland to capture CO2, improving rural\n\neconomies.", "The CO2 captured by ERW becomes stable bicarbonate, which improves soil health by\n\nremaining in the ocean for hundreds of years."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Enhanced rock weathering (ERW) is a method of spreading crushed basalt on farmland to capture carbon dioxide (CO2) and improve soil health.

ERW increases crop yields and removes harmful CO2 from the air.

ERW offers a low-cost, low-tech alternative to expensive, energy-intensive carbon capture methods. The CO2 captured by ERW becomes stable bicarbonate in soil water, which eventually streams into

the ocean to remain safely stored for hundreds of years.
ERW can improve rural economies by reducing farmers’ need for fertilizers and increasing their earnings from carbon credits.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('7aba587c-1d9a-525d-94ab-8a4ab2b04848', 0, null, 'Farmers must consider how the variables affect one another: their "interplay."'),
  ('0582e097-7224-52b9-8d3c-ffa8ceb6951d', 3, null, 'Moving goods from arrival straight onto trucks maximizes "throughput," the volume handled.'),
  ('27b9c50d-36fa-5a26-b92f-d0e288817962', 2, null, 'The algorithms process quantifiable inputs such as demand and capacity: "parameters."'),
  ('17f52ca8-c024-5e91-be6d-00c66e7ea807', 1, null, 'The Phoenix story warns about the corrupting influence of power: an "admonition."'),
  ('7ac87c0f-8f98-58dd-a602-1ff4add9cf55', 1, null, 'The underlined sentence describes the arc trajectory, and the rest explains why (speeds too low to escape).'),
  ('34c7ebdd-bd2e-56af-b52d-7dba1cb5e485', 0, null, 'The points app is a concrete example of the "willing participation" Eggers criticizes.'),
  ('038929fd-e9fc-5e29-91bc-e0c7e1bc6017', 3, null, 'Both use palms as images of nature, but only Tagore feels his consciousness flowing into the "rustling palm leaves."'),
  ('56acb438-7f6e-5730-8c7c-77d3a19d913c', 1, null, 'Mexican s, with more tongue tension, came from Nahuatl, so Nahuatl s has more tension than Castilian s.'),
  ('37921344-f76f-5ff2-a190-0622c7afa49f', 3, null, 'Defining cyberpunk by 1980s pop-culture objects like mirrored sunglasses shows it as aesthetic.'),
  ('6830efd4-7711-5388-b140-600cbfe3a5ae', 3, null, 'Recording position significantly affected song rate and duration (p-values 0.03 and 0.002, both below 0.05).'),
  ('6d9d4cc7-3370-523a-a3e9-c02560831bd3', 0, null, 'Endless recontextualizing and new meanings with each repetition prevent a single fixed interpretation.'),
  ('ad64f3c3-c276-5a95-862c-80e84323963c', 3, null, 'Nanda Devi is 7,816 m high but has a prominence of only 3,139 m: the two values differ greatly.'),
  ('cbd8e4b5-a1d2-5b8c-ad71-2c8a9443f60a', 1, null, 'Both studies (1 and 13 individuals) are far below the 176 needed, so neither supports a comparison.'),
  ('a991cb56-62aa-5e76-84ee-58ff085cad4c', 1, null, 'Which nonlinguistic areas are involved depends on what is described, so the combination depends on context.'),
  ('a6ca75d7-04d5-591e-88ae-54d560cfd9ef', 2, null, 'Rare temperate species face competition from conspecifics, but niche distinction lets them use resources others don''t.'),
  ('10c8efb7-55aa-5c5f-9c55-e7def1bbb77a', 2, null, 'A colon introduces the explanation of the site''s age.'),
  ('99286ad7-2683-58c8-b4ce-9bd666b1fea8', 3, null, 'The plural subject "applications" takes "were."'),
  ('48ca3cdd-4c69-5695-aa1b-8f43ce6c98eb', 1, null, '"dictating that..." is a participial phrase; the main verb is "rejects."'),
  ('17451dc5-8518-5063-9ce3-d23817fd2557', 0, null, '"seeking an explanation..." modifies "archaeologists"; the main verb is "analyzed."'),
  ('747cb15b-06fc-5662-a374-3ba25aaaebe6', 2, null, 'A dash introduces the appositive; the comma after "that" pairs with the one after "framework."'),
  ('23a3a2cf-c16f-535f-b333-b454aa5b7288', 0, null, 'The parenthetical ends the first sentence; a new sentence begins with "Occurring."'),
  ('3fab4c26-bfa1-5b32-89b8-c6ef8cb04c89', 0, null, 'It produces sound through strings, so it is classed as a chordophone: "Thus."'),
  ('fb4ef6b8-91e6-5629-ad5b-e4e3bd214948', 1, null, 'The F-5 is an example of a sleek, aerodynamic vehicle.'),
  ('c8782dca-d79a-5291-99dc-b790cf325243', 1, null, 'The postcards are another simple record of time, like the date paintings: "Similarly."'),
  ('1492f34b-7beb-526f-a2ac-e1622e9a86d3', 1, null, 'The sentence reinforces that many parades honored sports achievements: "Indeed."'),
  ('cbb9c9c8-ee89-5b04-b73a-a57a5672db9d', 3, null, 'It contrasts the subjects: a political scene vs a tranquil everyday scene.'),
  ('63ef781c-ff84-51e2-87c5-ee997ea905e4', 1, null, 'Being low-cost and low-tech makes ERW better than expensive, energy-intensive methods.')
