insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('f79880cb-34d6-5898-935a-bac342940f53', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'The function $f$ is defined by the equation $f(x) = 100x + 7$. What is the value of $f(x)$ when $x = 5$?', '["$112$", "$135$", "$500$", "$507$"]'::jsonb, 1, null),
  ('f7693ea2-2c77-5919-996d-692658bd53bd', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'How many of these $25$ people in Kayla’s neighborhood had a height of at least $51 \text{in}$ but less than $55 \text{in}$ ?', '[]'::jsonb, 2, 'For a project, Kayla recorded the heights of $25$ people in her neighborhood. The histogram summarizes the heights, in inches (in), of these $25$ people in Kayla’s neighborhood. The first bar represents people with a height of at least $51 \text{in}$ but less than $53 \text{in}$. The second bar represents people with a height of at least $53 \text{in}$ but less than $55 \text{in}$, and so on.

![figure](/q/oct26/003.webp)'),
  ('8ac5f474-94bd-5916-9a2f-b054964a0c5d', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'Which expression is equivalent to $32x^{2} + 32$?', '["$32(x^{2} + 1)$", "$32(x^{2} + 32)$", "$32(32x^{2} + 1)$", "$32(x^{2} + \\frac{1}{32})$"]'::jsonb, 3, null),
  ('5644b854-43d7-5ddd-83a4-af3c744a70e4', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'If $2(x - 10) = (2)(80)$, what is the value of $x - 10$?', '["$8$", "$16$", "$80$", "$160$"]'::jsonb, 4, null),
  ('d7f9430d-2752-585f-89eb-bb922ba80ac4', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'Triangles $ABC$ and $A^{′}B^{′}C^{′}$ are shown. Triangle $ABC$ is dilated by a scale factor of $3$ to form triangle $A^{′}B^{′}C^{′}$. If the length of $\overline{AB}$ is $21$, what is the length of $\overline{A^{′}B^{′}}$?', '["$3$", "$7$", "$24$", "$63$"]'::jsonb, 5, '![figure](/q/oct26/004.webp)'),
  ('0d091f7c-d180-579c-9fb6-89630e13bf15', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'What is an $x$-intercept of the graph of $y = x^{2} - 81$ in the xy-plane?', '["$(1,0)$", "$(9,0)$", "$(18,0)$", "$(81,0)$"]'::jsonb, 6, null),
  ('0ef3f875-bb00-51bd-b291-f28284f6dc5b', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'A store sells two different-sized bottles of a certain shampoo. The store’s sales of this shampoo totaled $910.53$ dollars last month. The equation $4.59x + 6.09y = 910.53$ represents this situation, where $x$ is the number of smaller bottles sold and $y$ is the number of larger bottles sold. According to the equation, what is the price, in dollars, of each smaller bottle?', '[]'::jsonb, 7, null),
  ('6fa3a591-e6a9-54e5-a2d2-e7b85a87ea24', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'Triangle $ABC$ is similar to triangle $XY Z$, where $A$, $B$, and $C$ correspond to $X$, $Y$, and $Z$, respectively. In triangle $ABC$, the length of $\overline{AB}$ is $180$ and the length of $\overline{BC}$ is $900$. In triangle $XY Z$, the length of $\overline{Y Z}$ is $80$. What is the length of $\overline{XY}$?', '["$288$", "$196$", "$80$", "$16$"]'::jsonb, 8, null),
  ('fe3dd6a0-9ad2-5da3-9a56-3fe2a3fdb519', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'In the xy-plane, line $k$ passes through the points $(0,-9)$ and $(1,-5)$. Which equation defines line $k$?', '["$y = \\frac{1}{4}x - 9$", "$y = -x + \\frac{1}{4}$", "$y = 4x - 9$", "$y = -x + 4$"]'::jsonb, 9, null),
  ('bfcfd38c-c84f-5765-b729-3fdba17a368e', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'Which of the following equations is the most appropriate linear model for the data shown in the scatterplot?', '["$y = 0.2 + 2.28x$", "$y = 0.2 - 2.28x$", "$y = 2.28 + 0.2x$", "$y = 2.28 - 0.2x$"]'::jsonb, 10, '![figure](/q/oct26/005.webp)'),
  ('fc5f2bc3-4da8-5701-85f3-d3a22e2fc273', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$g(x) = (24 - 2x)(10 + 2x)$
The function $g$ is defined by the given equation. For what value of $x$ does $g(x)$ reach its maximum?', '["$3.5$", "$7$", "$8.5$", "$17$"]'::jsonb, 11, null),
  ('4a778969-80cf-5300-a332-62483c6f91f7', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'An exponential function $f$ is defined by $f(x) = k(2)^{x}$, where $k$ is a positive constant. If $f(-1) = 8$ and $f(2) = 64$, what is the value of $k$?', '["$8$", "$9$", "$15$", "$16$"]'::jsonb, 12, null),
  ('988466e1-26a6-5ab2-a2c6-c0fb10888df8', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'The base of a right rectangular pyramid has a length of $27$ centimeters and a width of $7$ centimeters. The height of this pyramid is $5$ centimeters. What is the volume, in cubic centimeters, of this pyramid?', '[]'::jsonb, 13, null),
  ('a72cc061-8b26-5d58-84ae-f542551b7cee', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$66 = \frac{2K}{v^{2}}$
For an object with a mass of $66$ kilograms, the given equation relates the kinetic energy $K$, in joules, of the object to the object’s speed $v$, in meters per second, where $K$ and $v$ are positive. Which equation correctly expresses this object’s speed, in meters per second, in terms of the object’s kinetic energy, in joules?', '["$v = \\frac{2K}{66^{2}}$", "$v = \\frac{66^{2}}{2K}$", "$v =\\sqrt{\\frac{66}{2K}}$", "$v =\\sqrt{\\frac{2K}{66}}$"]'::jsonb, 14, null),
  ('4bcc1ab2-710c-5e01-8c9a-55288898e2d2', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'If $\frac{j}{k} = 95$ and $\frac{36j}{12xk} = 95$, what is the value of $x$?', '["$\\frac{12}{95}$", "$\\frac{1}{3}$", "$3$", "$36$"]'::jsonb, 15, null),
  ('a37e87df-5274-549c-9bde-306ebb65e710', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$y \ge x + 15$
$y \le -5x - 15$
Which point $(x,y)$ is a solution to the given system of inequalities in the xy-plane?', '["$(-6,13)$", "$(-6,8)$", "$(-4,13)$", "$(-4,8)$"]'::jsonb, 16, null),
  ('9c1dde7c-07fa-5bdf-89a8-3097a746257e', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'A plumbing company charges its customers \$111 for the first hour of a plumbing service call and \$50 for each additional hour, plus the cost of plumbing parts. Which equation represents the total cost $y$, in dollars, for an $x$-hour plumbing service call where the cost of parts was \$z and $x \ge 1$?', '["$y = 50x + z$", "$y = 50x + z + 61$", "$y = 111x + z$", "$y = 111x + 50z + 61$"]'::jsonb, 17, null),
  ('161577e2-4116-5f4b-a2fc-ebbf6f8df180', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'In the triangle shown, the value of $x$ is $8$. What is the value of $\sin A$?', '["$\\frac{1}{\\sqrt{3}}$", "$\\frac{1}{\\sqrt{2}}$", "$1$", "$\\sqrt{2}$"]'::jsonb, 18, '![figure](/q/oct26/006.webp)'),
  ('3f83abbe-330e-58dc-afc8-c6f56c580a93', '7d390e2e-0e52-5bca-b00f-41995a003e58', 'The shaded region shown represents the solutions to the inequality $-19y < c$, where $c$ is a constant. What is the value of $c$?', '["$114$", "$6$", "$-6$", "$-114$"]'::jsonb, 19, '![figure](/q/oct26/007.webp)'),
  ('1a4cda6a-6ef5-5fec-b431-3db7f6559fa8', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$y = x - 1$
$y = 27(x - 1)^{2} - 28$
A solution to the given system of equations is $(x,y)$. What is one possible value of $x - 1$?', '["$-2$", "$-\\frac{28}{27}$", "$-1$", "$-\\frac{1}{27}$"]'::jsonb, 20, null),
  ('9b26b4e6-e30f-5dc7-8419-9230f550f96b', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$10x + 14y = 6y + 5$
$ty = \frac{1}{3} + 5x$
In the given system of equations, $t$ is a constant. If the system has no solution, what is the value of $t$?', '[]'::jsonb, 21, null),
  ('19bd7bb4-e946-5357-ba4f-c2843c05d8b5', '7d390e2e-0e52-5bca-b00f-41995a003e58', '$4∣x + 3∣ - 2 = 22$
What is the sum of the solutions to the given equation?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('f79880cb-34d6-5898-935a-bac342940f53', 3, null, '$f(5) = 100(5) + 7 = 507$.'),
  ('f7693ea2-2c77-5919-996d-692658bd53bd', null, array['10']::text[], 'The first two bars (51-53 and 53-55 in) have 4 and 6 people: $10$.'),
  ('8ac5f474-94bd-5916-9a2f-b054964a0c5d', 0, null, 'Factor out 32: $32(x^{2} + 1)$.'),
  ('5644b854-43d7-5ddd-83a4-af3c744a70e4', 2, null, 'Divide both sides by 2: $x - 10 = 80$.'),
  ('d7f9430d-2752-585f-89eb-bb922ba80ac4', 3, null, 'A dilation by 3 multiplies lengths by 3: $3(21) = 63$.'),
  ('0d091f7c-d180-579c-9fb6-89630e13bf15', 1, null, '$x^{2} = 81$ gives $x = \pm 9$; $(9, 0)$ is listed.'),
  ('0ef3f875-bb00-51bd-b291-f28284f6dc5b', null, array['4.59']::text[], 'The coefficient of $x$ is the price of each smaller bottle: \$4.59.'),
  ('6fa3a591-e6a9-54e5-a2d2-e7b85a87ea24', 3, null, '$\frac{AB}{BC} = \frac{180}{900} = \frac{1}{5}$, so $XY = \frac{80}{5} = 16$.'),
  ('fe3dd6a0-9ad2-5da3-9a56-3fe2a3fdb519', 2, null, 'Slope $\frac{-5 - (-9)}{1 - 0} = 4$ and $y$-intercept $-9$: $y = 4x - 9$.'),
  ('bfcfd38c-c84f-5765-b729-3fdba17a368e', 0, null, 'The points rise about 2.3 per unit of $x$ from near the origin: $y = 0.2 + 2.28x$.'),
  ('fc5f2bc3-4da8-5701-85f3-d3a22e2fc273', 0, null, 'The zeros are $12$ and $-5$; the maximum is midway, at $x = 3.5$.'),
  ('4a778969-80cf-5300-a332-62483c6f91f7', 3, null, '$f(2) = 4k = 64$, so $k = 16$ (and $f(-1) = \frac{16}{2} = 8$ checks).'),
  ('988466e1-26a6-5ab2-a2c6-c0fb10888df8', null, array['315']::text[], '$\frac{1}{3}(27)(7)(5) = 315$.'),
  ('a72cc061-8b26-5d58-84ae-f542551b7cee', 3, null, '$66v^{2} = 2K$, so $v = \sqrt{\frac{2K}{66}}$.'),
  ('4bcc1ab2-710c-5e01-8c9a-55288898e2d2', 2, null, '$\frac{36j}{12xk} = \frac{3}{x} \cdot \frac{j}{k} = \frac{3}{x}(95) = 95$, so $x = 3$.'),
  ('a37e87df-5274-549c-9bde-306ebb65e710', 0, null, '$(-6, 13)$: $13 \ge 9$ and $13 \le 15$, so both inequalities hold.'),
  ('9c1dde7c-07fa-5bdf-89a8-3097a746257e', 1, null, '$111 + 50(x - 1) + z = 50x + z + 61$.'),
  ('161577e2-4116-5f4b-a2fc-ebbf6f8df180', 1, null, 'A 45-45-90 triangle: $\sin 45° = \frac{1}{\sqrt{2}}$.'),
  ('3f83abbe-330e-58dc-afc8-c6f56c580a93', 0, null, 'The shaded region is $y > -6$, so $-19y < 114$: $c = 114$.'),
  ('1a4cda6a-6ef5-5fec-b431-3db7f6559fa8', 2, null, 'With $u = x - 1$: $27u^{2} - u - 28 = 0$, so $u = -1$ or $u = \frac{28}{27}$.'),
  ('9b26b4e6-e30f-5dc7-8419-9230f550f96b', null, array['-4']::text[], 'The system is $10x + 8y = 5$ and $-5x + ty = \frac{1}{3}$. Parallel lines need $\frac{10}{-5} = \frac{8}{t}$, so $t = -4$.'),
  ('19bd7bb4-e946-5357-ba4f-c2843c05d8b5', null, array['-6']::text[], '$|x + 3| = 6$ gives $x = 3$ or $x = -9$; the sum is $-6$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

