values ('14affc84-9296-5237-a683-4f7cb6a93179', 'PeaklyTest Oct 2026 · Math · Module 2', 'Math', 'Math, Module 2 of the Oct 2026 PeaklyTest · 22 questions · 35 minutes', 35, 103, true, 'PeaklyTest Oct 2026 · Math', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
