insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('cf985a98-59c7-5bea-bb54-1396386f9f56', '14affc84-9296-5237-a683-4f7cb6a93179', 'In the figure shown, lines $ℓ$ and $k$ are parallel and line $t$ intersects both lines. If $x > 120$, which of the following must be true?', '["$y < 60$", "$y > 60$", "$x + y < 180$", "$x + y > 180$"]'::jsonb, 1, '![figure](/q/oct26/008.webp)'),
  ('3ec86ee4-9b92-52bb-8fae-1344d2a1fe02', '14affc84-9296-5237-a683-4f7cb6a93179', 'The roofs on the buildings of a public garden are designed to allow water to drain into the garden. The table shows the relationship between the area $x$, in square feet, of a roof and the amount of water $f(x)$, in gallons, drained from the roof into the garden over a certain period of time. Which equation could define $f$?', '["$f(x) = 0.6x$", "$f(x) = 2.4x$", "$f(x) = 1,248.0x$", "$f(x) = 2,496.0x$"]'::jsonb, 2, '| Area (square feet) | Water (gallons) |
| $1,040$ | $2,496$ |
| $1,560$ | $3,744$ |
| $2,080$ | $4,992$ |'),
  ('82a5e709-8019-5a38-a12b-95c8ef90f313', '14affc84-9296-5237-a683-4f7cb6a93179', '$13x + 325 = a(x + 25)$
In the given equation, $a$ is a constant. If the equation has infinitely many solutions, what is the value of $a$?', '[]'::jsonb, 3, null),
  ('9073d4b7-7bd3-52d9-81ae-805ebfdd9971', '14affc84-9296-5237-a683-4f7cb6a93179', '$y = -\frac{1}{11}x$
$y = \frac{1}{4}x$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '["$-11$", "$-7$", "$0$", "$4$"]'::jsonb, 4, null),
  ('8a9c690f-713c-5b1a-aa74-01d2229e4f09', '14affc84-9296-5237-a683-4f7cb6a93179', 'An organization sells tickets to a fundraiser for \$50 per person. The organization’s expenses are \$600 for a rental space and \$18 per person for food. The organization’s goal is to earn at least \$1,500 after paying all expenses. What is the minimum number of tickets that must be sold to meet this goal?', '["$30$", "$42$", "$47$", "$66$"]'::jsonb, 5, null),
  ('dfc81564-21fb-546a-af87-4ea15affb7d9', '14affc84-9296-5237-a683-4f7cb6a93179', '$f(x) = \frac{a - 15}{x} + 5$
In the given function $f$, $a$ is a constant. The graph of function $f$ in the xy-plane, where $y = f(x)$, is translated $3$ units down and $2$ units to the right to produce the graph of $y = g(x)$. Which equation defines function $g$?', '["$g(x) = \\frac{a-15}{x+2} + 2$", "$g(x) = \\frac{a-15}{x-2} + 2$", "$g(x) = \\frac{a-18}{x+2} + 5$", "$g(x) = \\frac{a-18}{x-2} + 5$"]'::jsonb, 6, null),
  ('c97cd6df-e8fa-5dbe-9d00-eb0c4ff13188', '14affc84-9296-5237-a683-4f7cb6a93179', 'The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit for the data is also shown. For how many of the $9$ data points does the line of best fit predict a $y$-value that is less than the actual $y$-value?', '["$9$", "$6$", "$3$", "$0$"]'::jsonb, 7, '![figure](/q/oct26/009.webp)'),
  ('e13bdb1a-8512-592b-b9ca-ceafcb70eaab', '14affc84-9296-5237-a683-4f7cb6a93179', 'Line $p$ is defined by $2y + 18x = 11$. Line $r$ is perpendicular to line $p$ in the xy-plane. What is the slope of line $r$?', '["$9$", "$\\frac{1}{9}$", "$-\\frac{1}{9}$", "$-9$"]'::jsonb, 8, null),
  ('85098363-ba7f-5ecf-b5c5-8f0718684cad', '14affc84-9296-5237-a683-4f7cb6a93179', 'What is the $y$-intercept of the graph of $y = (\frac{2}{17})^{x+1}$ in the xy-plane?', '["$(2,17)$", "$(0,17)$", "$(0,2)$", "$(0, \\frac{2}{17})$"]'::jsonb, 9, null),
  ('a3127543-b0aa-54b7-af63-4e6694ba8ff4', '14affc84-9296-5237-a683-4f7cb6a93179', 'A beaker containing a liquid is placed on a table. The function $g(t) = 294 + (364 - 294)(2.72)^{-0.104t}$ gives the approximate temperature, in kelvins, of the liquid $t$ minutes after the beaker was placed on the table. According to this function, what was the approximate temperature, in kelvins, of the liquid when the beaker was placed on the table?', '[]'::jsonb, 10, null),
  ('c3ffe215-6233-5815-b43c-a13fcc8c2352', '14affc84-9296-5237-a683-4f7cb6a93179', 'Hannah and Wyatt are saving money to purchase a car. Hannah saves $\frac{1}{5}$ of her salary each month, and Wyatt saves $\frac{2}{7}$ of his salary each month. Together, they save a total of \$3,160 from their monthly salaries each month. If $h$ and $w$ represent Hannah’s and Wyatt’s monthly salaries, in dollars, respectively, which equation shows the relationship between $h$ and $w$?', '["$h + w = 3,160$", "$h + 2w = 3,160$", "$10h + 7w = 110,600$", "$7h + 10w = 110,600$"]'::jsonb, 11, null),
  ('be7d0b98-8834-5c21-9878-0c917b2ac7a7', '14affc84-9296-5237-a683-4f7cb6a93179', '$f(x) =\sqrt{7x + 6}$
The function $f$ is defined by the given equation. If $f(a) = -7a$, where $a$ is a constant, what is the value of $a$?', '["$-\\frac{3}{7}$", "$-\\frac{2}{7}$", "$\\frac{2}{7}$", "$\\frac{3}{7}$"]'::jsonb, 12, null),
  ('4f0f0a0e-7cf9-59b7-9d1d-c317059b82e8', '14affc84-9296-5237-a683-4f7cb6a93179', 'A car dealership has only sedans, SUVs, and minivans for sale. On Monday, $20%$ of the vehicles for sale were sedans and $50%$ were SUVs. If there were $22$ sedans for sale at the dealership on Monday, how many minivans were for sale?', '[]'::jsonb, 13, null),
  ('8ba9f148-ecd5-5726-9faa-dd6854da36b6', '14affc84-9296-5237-a683-4f7cb6a93179', '$4x^{2} + 14 = 32x + r$
In the given equation, $r$ is a constant. The equation has exactly one real solution. What is the value of $r$?', '[]'::jsonb, 14, null),
  ('ee833bd9-5e0c-5069-bb95-98584678d34a', '14affc84-9296-5237-a683-4f7cb6a93179', 'In the figure, $3r > 11s$. Which of the following values must be the greatest?', '["$\\sin r°$", "$\\cos r°$", "$\\frac{\\sin r°}{\\sin s°}$", "$\\frac{\\sin r°}{\\cos s°}$"]'::jsonb, 15, '![figure](/q/oct26/010.webp)'),
  ('eba79a29-06f5-5fbd-a699-9487e9662562', '14affc84-9296-5237-a683-4f7cb6a93179', 'If the results of this study suggest a relationship between melatonin levels and the amount of time spent playing video games, which of the following aspects of the study will prevent the results from being generalized to all gamers?', '["The melatonin levels of the selected gamers were not measured over a long enough period of time.", "The number of selected gamers from each country is different.", "The number of selected gamers is too small.", "The gamers were not selected at random from all gamers."]'::jsonb, 16, 'A researcher conducted a study to examine the melatonin levels of gamers and the amount of time the gamers spent playing video games. A total of $127$ gamers were selected at random from three countries. The melatonin levels of the gamers and the amount of time they spent playing video games were recorded over a $4$-week period. The table gives the number of selected gamers from each country.

| Country | Sweden | South Korea | United States |
| **Number of gamers** | $25$ | $49$ | $53$ |'),
  ('f61b836e-fe1b-5bab-b73f-4bbbc9444491', '14affc84-9296-5237-a683-4f7cb6a93179', 'The line segment shown in the xy-plane represents one of the legs of a right triangle. The area of this triangle is $42\sqrt{13}$ square units. What is the length, in units, of the other leg of this triangle?', '[]'::jsonb, 17, '![figure](/q/oct26/011.webp)'),
  ('36ef81d9-12f1-5f64-a480-a92b0d7ab974', '14affc84-9296-5237-a683-4f7cb6a93179', '$-12(5x - 3)^{2} + 6(5x - 4)^{2}$
The given expression can be rewritten as $\frac{a}{6}x^{2} + \frac{b}{6}x + \frac{c}{6}$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', '["$-252$", "$-126$", "$-42$", "$-7$"]'::jsonb, 18, null),
  ('16099d9a-5ad5-5791-bf34-8df0dff6925a', '14affc84-9296-5237-a683-4f7cb6a93179', 'The graph of the linear function $y = g(x) - 17$ is shown. If $a$ and $b$ are positive constants, which equation could define $g$?', '["$g(x) = -ax + b$", "$g(x) = ax - b$", "$g(x) = ax + b$", "$g(x) = -ax - b$"]'::jsonb, 19, '![figure](/q/oct26/012.webp)'),
  ('713c8b7c-2622-5edb-959c-1ac585144647', '14affc84-9296-5237-a683-4f7cb6a93179', 'A circle has center $G$, and points $M$ and $N$ lie on the circle. Line segments $MH$ and $NH$ are tangent to the circle at points $M$ and $N$, respectively. If the radius of the circle is $238$ millimeters and the perimeter of quadrilateral $GMHN$ is $4,508$ millimeters, what is the distance, in millimeters, between points $G$ and $H$?', '["$238$", "$2,002$", "$2,016$", "$2,030$"]'::jsonb, 20, null),
  ('1604672d-223b-5dd3-9dbf-9e1371937d2c', '14affc84-9296-5237-a683-4f7cb6a93179', '$h(x) = a(x + 43)(x + r)(x + s)$
The polynomial function $h$ is defined by the given equation, where $a$, $r$, and $s$ are positive constants. In the xy-plane, the graph of $y = h(x)$ intersects the $x$-axis at exactly three points. If $h(0) = p$, which of the following must be true?', '["$p < 43rs$", "$p = 43rs$", "$p > 43rs$", "There is not enough information to compare the values of $p$ and $43rs$."]'::jsonb, 21, null),
  ('61c82810-4e81-523d-a03d-6e9d98af3e72', '14affc84-9296-5237-a683-4f7cb6a93179', 'The mass of object A is $462%$ of the mass of object B, and the mass of object A is $0.084%$ of the mass of object C. If the mass of object C is $p%$ of the mass of object B, what is the value of $\frac{p}{1,000}$?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('cf985a98-59c7-5bea-bb54-1396386f9f56', 0, null, 'Angle $y$ equals the angle supplementary to $x$ (parallel lines), so $x + y = 180$; $x > 120$ means $y < 60$.'),
  ('3ec86ee4-9b92-52bb-8fae-1344d2a1fe02', 1, null, '$\frac{2,496}{1,040} = 2.4$ for every row: $f(x) = 2.4x$.'),
  ('82a5e709-8019-5a38-a12b-95c8ef90f313', null, array['13']::text[], '$a(x + 25) = ax + 25a$ must equal $13x + 325$, so $a = 13$.'),
  ('9073d4b7-7bd3-52d9-81ae-805ebfdd9971', 2, null, '$-\frac{1}{11}x = \frac{1}{4}x$ only when $x = 0$.'),
  ('8a9c690f-713c-5b1a-aa74-01d2229e4f09', 3, null, '$50n - 18n - 600 \ge 1,500$ gives $n \ge 65.6$, so 66 tickets.'),
  ('dfc81564-21fb-546a-af87-4ea15affb7d9', 1, null, 'Right 2 replaces $x$ with $x - 2$; down 3 changes $+5$ to $+2$.'),
  ('c97cd6df-e8fa-5dbe-9d00-eb0c4ff13188', 2, null, 'Only 3 points lie above the line: near $x = 4$, $5$ and $9$.'),
  ('e13bdb1a-8512-592b-b9ca-ceafcb70eaab', 1, null, 'Line $p$: $y = -9x + \frac{11}{2}$, slope $-9$; the perpendicular slope is $\frac{1}{9}$.'),
  ('85098363-ba7f-5ecf-b5c5-8f0718684cad', 3, null, 'At $x = 0$: $y = (\frac{2}{17})^{1} = \frac{2}{17}$.'),
  ('a3127543-b0aa-54b7-af63-4e6694ba8ff4', null, array['364']::text[], 'At $t = 0$: $294 + (364 - 294)(1) = 364$ kelvins.'),
  ('c3ffe215-6233-5815-b43c-a13fcc8c2352', 3, null, '$\frac{h}{5} + \frac{2w}{7} = 3,160$; multiplying by 35 gives $7h + 10w = 110,600$.'),
  ('be7d0b98-8834-5c21-9878-0c917b2ac7a7', 1, null, '$7a + 6 = 49a^{2}$ gives $a = \frac{3}{7}$ or $-\frac{2}{7}$; $-7a$ must be non-negative, so $a = -\frac{2}{7}$.'),
  ('4f0f0a0e-7cf9-59b7-9d1d-c317059b82e8', null, array['33']::text[], '$22$ sedans are 20%, so there are 110 vehicles; minivans are 30%: $33$.'),
  ('8ba9f148-ecd5-5726-9faa-dd6854da36b6', null, array['-50']::text[], '$4x^{2} - 32x + (14 - r) = 0$ has one solution when $32^{2} = 16(14 - r)$, so $r = -50$.'),
  ('ee833bd9-5e0c-5069-bb95-98584678d34a', 2, null, '$r + s = 90$ and $3r > 11s$ give $r > 70.7$. $\frac{\sin r°}{\sin s°} = \tan r° > 2.8$, while the others are at most 1.'),
  ('eba79a29-06f5-5fbd-a699-9487e9662562', 3, null, 'The gamers came from only three countries, not at random from all gamers.'),
  ('f61b836e-fe1b-5bab-b73f-4bbbc9444491', null, array['28']::text[], 'The leg is $\sqrt{9^{2} + 6^{2}} = 3\sqrt{13}$; $\frac{1}{2}(3\sqrt{13})L = 42\sqrt{13}$ gives $L = 28$.'),
  ('36ef81d9-12f1-5f64-a480-a92b0d7ab974', 0, null, 'The expression is $-150x^{2} + 120x - 12$, so $a = -900$, $b = 720$, $c = -72$ and $a + b + c = -252$.'),
  ('16099d9a-5ad5-5791-bf34-8df0dff6925a', 2, null, '$g(x) - 17 = 3x - 7$, so $g(x) = 3x + 10$: $ax + b$ with positive $a$ and $b$.'),
  ('713c8b7c-2622-5edb-959c-1ac585144647', 3, null, '$2(238) + 2(MH) = 4,508$ gives $MH = 2,016$. $GH = \sqrt{238^{2} + 2,016^{2}} = 2,030$.'),
  ('1604672d-223b-5dd3-9dbf-9e1371937d2c', 3, null, '$p = h(0) = 43ars$, which can be more or less than $43rs$ depending on $a$.'),
  ('61c82810-4e81-523d-a03d-6e9d98af3e72', null, array['550']::text[], '$A = 4.62B = 0.00084C$, so $C = 5,500B$ and $p = 550,000$: $\frac{p}{1,000} = 550$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
